const hostingSiteList = `-- name: HostingSiteList :many
SELECT id, account_id, project_id, environment, name, hostname, origin_id, status, active_release_id, revision, created_at, durable_routing, suspended FROM hosting_sites WHERE account_id = $1::uuid ORDER BY id
`

func (q *Queries) HostingSiteList(ctx context.Context, db DBTX, accountID pgtype.UUID) ([]HostingSite, error) {
	rows, err := db.Query(ctx, hostingSiteList, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []HostingSite{}
	for rows.Next() {
		var i HostingSite
		if err := rows.Scan(
			&i.ID,
			&i.AccountID,
			&i.ProjectID,
			&i.Environment,
			&i.Name,
			&i.Hostname,
			&i.OriginID,
			&i.Status,
			&i.ActiveReleaseID,
			&i.Revision,
			&i.CreatedAt,
			&i.DurableRouting,
			&i.Suspended,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

